    fun readInt(): Int {
        val d = reader.readLine().trim()
        return d.toInt()
    }

    fun readArrayOfInt(size: Int, indexFrom: Int = 0): IntArray {
        val parts = reader.readLine().trim().split(" ")
        val a = IntArray(size + indexFrom)
        var ind = indexFrom
        for (item in parts) {
            a[ind++] = item.toInt()
        }
        return a
    }

    fun readArrayOfString(size: Int, indexFrom: Int = 0): Array<String> {
        val parts = reader.readLine().trim().split(" ")
        val a = Array(size + indexFrom) { "" }
        var ind = indexFrom
        for (item in parts) {
            a[ind++] = item
        }
        return a
    }
}

object Utils {
    fun <T> ntimes(n: Int, func: () -> T, returnResults: Boolean = false): List<T> {
        val a = mutableListOf<T>()
        for (i in 1..n) {
            val result = func()
            if (returnResults) {
                a.add(result)
            }
        }
        return a
    }

    fun cumsum(a: MutableMap<Int, Int>) {
        var sum = 0
        for ((k, v) in a.toSortedMap()) {
            val newVal = v + sum
            a[k] = newVal
            sum = newVal
        }
    }

    fun diff(a: MutableMap<Int, Int>) {
        var prev = 0
        for ((k, v) in a.toSortedMap()) {
            val buf = v
            a[k] = v - prev
            prev = buf
        }
    }

    fun bitCount(n: Int): Int {
        var cnt = 0
        var j = n
        while (j != 0) {
            cnt += j and 1
            j = j ushr 1
        }
        return cnt
    }
}

object PrimeUtils {
    private val divisorsCache: MutableMap<Int, MutableMap<Int, Boolean>> = mutableMapOf(
        1 to mutableMapOf(1 to true),
        2 to mutableMapOf(1 to true, 2 to true)
    )
    private var primes: MutableMap<Int, Int> = mutableMapOf()

    private fun primes(limit: Int): Sequence<Int> = sequence {
        val size = (limit shr 3) + 1
        val a = ByteArray(size) { 85.toByte() }
        a[0] = 83.toByte()
        var i = 3
        while (i * i < limit) {
            if ((a[i shr 3].toInt() and (1 shl (i % 8))) != 0) {
                // do nothing
            } else {
                var k = i
                while (k * i < limit) {
                    val n = k * i
                    a[n shr 3] = (a[n shr 3].toInt() or (1 shl (n % 8))).toByte()
                    k++
                }
            }
            i += 2
        }
        yield(2)
        i = 3
        while (i < limit) {
            if ((a[i shr 3].toInt() and (1 shl (i % 8))) == 0) {
                yield(i)
            }
            i += 2
        }
    }

    fun divisors(n: Int, lp: Int = 2): MutableMap<Int, Boolean> {
        divisorsCache[n]?.let { return it }
        if (primes.isEmpty()) {
            val primesMap = mutableMapOf<Int, Int>()
            for (prime in primes(1000)) {
                primesMap[prime] = prime
            }
            primes = primesMap
        }
        val r = mutableMapOf<Int, Boolean>()
        for ((p, _) in primes) {
            if (p >= lp) {
                if (n < p * p) {
                    r[1] = true
                    r[n] = true
                    break
                } else if (n % p == 0) {
                    val preList = listOf(1, p)
                    val subDiv = divisors(n / p, p)
                    for (pre in preList) {
                        for ((nxt, _) in subDiv) {
                            r[nxt * pre] = true
                        }
                    }
                    break
                }
            }
        }
        divisorsCache[n] = r
        return r
    }
}

fun main() {
    val ir = InputReader()
    val arr = ir.readArrayOfInt(2)
    val n = arr[0]
    val k = arr[1]
    val xs = mutableListOf<Long>()
    val divs = PrimeUtils.divisors(n)
    for ((divisor, _) in divs) {
        val l = divisor
        val m = n / l
        if (m < k) {
            xs.add(k.toLong() * l + m.toLong())
        }
    }
    if (xs.isEmpty()) {
        println(n.toLong() * k + 1)
    } else {
        var mn = xs[0]
        for (v in xs) {
            mn = min(mn, v)
        }
        println(mn)
    }
}

