    private var st: StringTokenizer? = null

    fun next(): String {
        while (st == null || !st!!.hasMoreElements()) {
            st = StringTokenizer(br.readLine())
        }
        return st!!.nextToken()
    }

    fun readInt(): Int = next().toInt()

    fun readArrayOfInt(size: Int, indexFrom: Int = 0): IntArray {
        val a = IntArray(size + indexFrom)
        var ind = indexFrom
        while (ind < size + indexFrom) {
            a[ind++] = readInt()
        }
        return a
    }

    fun readArrayOfString(size: Int, indexFrom: Int = 0): Array<String?> {
        val a = arrayOfNulls<String>(size + indexFrom)
        var ind = indexFrom
        while (ind < size + indexFrom) {
            a[ind++] = next()
        }
        return a
    }
}

object Utils {
    fun <T> ntimes(n: Int, func: () -> T, returnResults: Boolean = false): Map<Int, T> {
        val a = mutableMapOf<Int, T>()
        for (i in 1..n) {
            val result = func()
            if (returnResults) {
                a[i] = result
            }
        }
        return a
    }

    fun cumsum(a: MutableMap<Int, Int>) {
        var sum = 0
        val keys = a.keys.sorted()
        for (k in keys) {
            a[k] = a[k]!! + sum
            sum = a[k]!!
        }
    }

    fun diff(a: MutableMap<Int, Int>) {
        var prev = 0
        val keys = a.keys.sorted()
        for (k in keys) {
            val buf = a[k]!!
            a[k] = a[k]!! - prev
            prev = buf
        }
    }

    fun bitCount(n: Int): Int {
        var cnt = 0
        var j = n
        while (j != 0) {
            cnt += j and 1
            j = j shr 1
        }
        return cnt
    }
}

object PrimeUtils {
    private val divisors: MutableMap<Long, MutableMap<Long, Boolean>> = mutableMapOf(
        1L to mutableMapOf(1L to true),
        2L to mutableMapOf(1L to true, 2L to true)
    )
    private var primes: MutableMap<Long, Long> = mutableMapOf()

    private fun primes(limit: Int): Sequence<Long> = sequence {
        val size = (limit shr 3) + 1
        val a = ByteArray(size) { 85.toByte() }
        a[0] = 83.toByte()
        var i = 3
        while (i * i < limit) {
            if ((a[i shr 3].toInt() and (1 shl (i % 8))) != 0) {
            } else {
                var k = i
                while (k * i < limit) {
                    val n = k * i
                    a[n shr 3] = (a[n shr 3].toInt() or (1 shl (n % 8))).toByte()
                    k++
                }
            }
            i += 2
        }
        yield(2L)
        i = 3
        while (i < limit) {
            if ((a[i shr 3].toInt() and (1 shl (i % 8))) == 0) {
                yield(i.toLong())
            }
            i += 2
        }
    }

    fun divisors(n: Long, lp: Long = 2L): MutableMap<Long, Boolean> {
        if (divisors.containsKey(n)) {
            return divisors[n]!!
        }
        if (primes.isEmpty()) {
            val ps = mutableMapOf<Long, Long>()
            for (prime in primes(1000)) {
                ps[prime] = prime
            }
            primes = ps
        }
        val r = mutableMapOf<Long, Boolean>()
        for (p in primes.values) {
            if (p >= lp) {
                if (n < p * p) {
                    r[1L] = true
                    r[n] = true
                    break
                } else if (n % p == 0L) {
                    val pres = listOf(1L, p)
                    for (pre in pres) {
                        for ((nxt, _) in divisors(n / p, p)) {
                            r[nxt * pre] = true
                        }
                    }
                    break
                }
            }
        }
        divisors[n] = r
        return divisors[n]!!
    }
}

